<script setup>import{Link,router,usePage}from'@inertiajs/vue3';const props=defineProps({product:Object,compactMobile:{type:Boolean,default:false},showDescription:{type:Boolean,default:true}}),page=usePage();const money=v=>new Intl.NumberFormat('en-TZ',{style:'currency',currency:page.props.store.currency,maximumFractionDigits:0}).format(v||0);const add=()=>router.post(`/cart/${props.product.slug}`,{quantity:1},{preserveScroll:true});</script><template><article class="group card flex h-full flex-col overflow-hidden"><Link :href="`/products/${product.slug}`" class="relative block aspect-square overflow-hidden bg-slate-100"><img :src="product.image_url" :alt="product.name" class="h-full w-full object-cover transition group-hover:scale-105" loading="lazy"><span class="absolute bottom-2 left-2 rounded-[8px] px-2 py-1 text-[10px] font-black" :class="product.in_stock?'bg-emerald-100 text-emerald-700':'bg-red-100 text-red-700'">{{product.in_stock?'In stock':'Out of stock'}}</span></Link><div class="flex flex-1 flex-col p-3 sm:p-4"><p class="text-[10px] font-black uppercase tracking-wider text-prinx-600">{{product.category?.name||'Electronics'}}</p><Link :href="`/products/${product.slug}`" class="mt-2 line-clamp-2 font-black text-slate-950 hover:text-prinx-600">{{product.name}}</Link><p v-if="showDescription&&product.short_description" class="mt-2 line-clamp-2 text-sm text-slate-500">{{product.short_description}}</p><div class="mt-auto flex items-end justify-between gap-2 pt-4"><div><div class="font-black">{{money(product.current_price)}}</div><div v-if="Number(product.current_price)<Number(product.price)" class="text-xs text-slate-400 line-through">{{money(product.price)}}</div></div><button class="h-10 w-10 rounded-[9px] bg-slate-950 text-white disabled:opacity-40" :disabled="!product.in_stock" @click="add">+</button></div></div></article></template>
